			return BONUS_HOUSE
	return 0.0

# 2.3 Firekeeper: вид-бонус (harpy — скорость, lizard — Resolve)
static func apply_firekeeper(settle) -> void:
	var fk_id: String = settle.state.get("firekeeper_id", "")
	if fk_id == "":
		return
	for s in settle.state["settlers"]:
		if s["id"] == fk_id:
			if s["species"] == "lizard":
